// D5·C 代谈进度 + D11·A 在线简历批注版 —— 候选详情（企业端），同构镜像 在谈详情。
//
// 一个候选点开就是这一页：两个 Tab（进度 = 代谈进度流，资料 = 在线简历），
// 版式与 Tab 行收进共用外壳（组件/在谈详情/详情外壳），Mock / Backend 同一版式。
// 代谈进度 = 按阶段分段的双方代理对话流（2026-08-20 重构，见 组件/阶段对话流），
// 与求职端共用同一个组件、同一套版式 —— 差别只有视角（我方 = 企业代理）与文案。
//
// 披露硬约束（产品契约 2026-08-25）：候选人真名与联系方式在 S1 简历原件递交后即对招聘方
// 可见，S0 候选仍只见代号与打码联系方式；意向确认（S3）只表示双方同意进入真人沟通，不再
// 承担首次交换身份。全屏不出现任何报价 / 出价 UI，薪资只属于岗位自己的带。
// 交互硬规矩与求职端相同：决策一律在这一页做，列表卡上不放按钮，
// 所以这一页是企业侧全局状态的唯一写入点：接受方案 / 终止 / 确认意向都从这里派发。
//
// P5 模式边界：Backend 的候选详情只渲染共享 P5 详情（屏幕/P5/MatchCase详情，role=
// recruiter，URL case_id + 已认证角色直达）—— 招聘端只有 candidate_alias（不透明展示
// 文本）与冻结职位，姓名/联系方式/结构化身份是 P5.1 依赖、不渲染；不读 企业候选列表、
// 不读匿名简历表。Mock 分支（Mock候选详情）行为与接线前逐字一致、零 P5 请求。

import { useEffect, useRef, useState } from 'react';
import { useParams, useSearchParams } from 'react-router-dom';
import 样式 from './候选详情.module.css';
import 拿不准弹层 from './拿不准弹层';
import 确认层 from '../组件/确认层';
import 阶段对话流, { type 分段项 } from '../组件/阶段对话流';
import { 次级页外壳, 返回栏 } from '../组件/通用';
import { 详情外壳 } from '../组件/在谈详情/详情外壳';
import { 详情动作卡 } from '../组件/在谈详情/详情动作卡';
import { 详情底栏 } from '../组件/在谈详情/详情底栏';
import type { 详情动作卡信息, 详情Tab, 详情底栏信息, 顶栏信息 } from '../组件/在谈详情/类型';
import { 拆画像 } from '../组件/候选头行';
import { 在线简历正文 } from '../组件/在谈详情/在线简历正文';
import { 招聘侧对齐行 } from '../数据/匹配对齐';
import 简历预览层 from '../组件/简历预览层';
import {
  各候选阶段对话,
  候选兜底对话,
  候选阶段小结,
  企业卡点决策,
  匿名简历表,
  候选简历原件表,
} from '../数据/企业端模拟数据';
import { 阶段顺序 } from '../数据/类型';
import type { 分歧, 候选, 阶段, 阶段小结 } from '../数据/类型';
import { use应用状态 } from '../状态/应用状态';
import { use导航 } from '../路由/导航钩子';
import { 路径 } from '../路由/路径表';
import { MatchCase详情 } from './P5/MatchCase详情';

/** Tab 名已收进共用外壳（详情Tab = 进度 | 资料）：本屏只持有当前 Tab，
 *  第二 Tab 的「在线简历」由 资料 槽位给出（与求职端 在谈详情 同构）。*/

/** 点决策那一刻冻结下来的卡点上下文（见 做协调决策 的注释） */
interface 决策快照内容 {
  分歧: 分歧 | null;
  决定文案: string;
  规则草案: string;
}

/** A-01（后来揭晓是沈亦舟）的卡点小结 —— 与这一单的分歧轴和阶段对话说同一件事：
 *  卡的是远程天数，不是到岗（到岗与薪资不在代理谈判范围内，产品边界 2026-08-18）*/
const 卡点小结A01 =
  '对方要每周 2 天远程，岗位现在是全现场，差 1 天。其余条件（薪资带 / 团队 12 人 / Go 主栈）均已一致，AI代理建议接受每周 1 天固定远程。';

/** 终止确认框的正文：直接用归档屏上那句已有的口径（归档谈判.tsx / 企业归档.tsx 的说明条），
 *  两端、两屏说同一句话，不为这个弹层另写一份解释 */
const 归档口径 =
  '已结束的单不会再恢复成在谈 —— 阶段只往前走。但全程往来记录一直留着，可以回看当时卡在哪一条上。';

/** 意向确认前唯一的告知（企业视角）：与求职端 意向确认警示 同构。
 *  同样不能再删 —— 理由见 模拟数据.ts 里那一条的注释。 */
const 企业意向确认警示 = '双方确认后进入真人沟通与约面';


// ── 弹层文案：必须带这一单的真实上下文（代号 + 卡点项 + 差值），不能用写死的示例句 ──
function 算决策文案(候: 候选, 类型: '接受' | '终止'): { 决定文案: string; 规则草案: string } {
  // 卡点项名从「对方要每周 2 天远程…」「主栈 Java 非 Go…」这类下一步文案里抠关键词。
  // 关键词只覆盖软性要求与硬性资历 —— 薪资与到岗不在代理谈判范围内（产品边界 2026-08-18）
  const 卡点项名 =
    /(远程|办公|作息|双休|大小周|加班|出差|团队|汇报|主栈|技术栈|年限|学历)/.exec(候.下一步)?.[1] ??
    '这一项';
  // '差 15 天' → '15 天'；「域对口」这类非数字差值不做净值拼接
  const 差值净 =
    候.分歧 && /^差\s*/.test(候.分歧.差值) ? 候.分歧.差值.replace(/^差\s*/, '') : null;
  // 差值末尾是英文单位（2K）时后面补一个空格，中文单位（15 天）时不补 —— 中英混排间距
  const 差值短语 = 差值净 ? (/[a-zA-Z]$/.test(差值净) ? `${差值净} ` : 差值净) : '';
  const 卡点描述 = 差值净 ? `在「${卡点项名}」上差 ${差值净}` : `在「${卡点项名}」这一项有分歧`;

  return 类型 === '终止'
    ? {
        // 代号已是中文昵称（陈屿），直接与后文相接，不再需要中英混排空格
        决定文案: `${候.代号}${卡点描述}，你选择不放宽 —— AI代理已终止接触并归档，不再消耗接触额度。`,
        规则草案: 差值净
          ? `${卡点项名}差超过 ${差值短语}的候选，直接终止，不用先问我`
          : `触到${卡点项名}这条线的候选，直接终止，不用先问我`,
      }
    : {
        决定文案: `${候.代号}${卡点描述}，你同意放宽 —— AI代理会立刻回报对方，等候选人确认意向。`,
        规则草案: 差值净
          ? `${卡点项名}差 ${差值短语}以内的候选，可以直接替我放宽`
          : `${卡点项名}这类域对口的分歧，可以直接替我放宽`,
      };
}

export default function 候选详情() {
  const { 数据源模式 } = use应用状态();
  // eslint-disable-next-line jsx-a11y/aria-role -- role 是 P5 域 prop，非 ARIA role
  return 数据源模式 === 'backend' ? <MatchCase详情 role="recruiter" /> : <Mock候选详情 />;
}

/** Mock 原型分支：静态候选表 + 全局归约，行为与接线前逐字一致（P5 Task 5 仅移入，未改）。 */
function Mock候选详情() {
  const { id: 编号 = '' } = useParams<{ id: string }>();
  const { 状态, 派发 } = use应用状态();
  const { 跳转, 返回 } = use导航();

  // 企业真人会话顶部「看简历」带 ?tab=resume 进来，直接开在在线简历（资料）Tab —— 产品负责人
  // 点名的重点就是「看简历要方便」，多一次点 Tab 就是把方便又还回去了。
  // 与求职端 在谈详情 同构：只在挂载时读一次，之后手点 Tab 不被地址栏拽回去。
  const [查询参数] = useSearchParams();
  const [当前Tab, 设当前Tab] = useState<详情Tab>(
    查询参数.get('tab') === 'resume' ? '资料' : '进度'
  );
  const [弹层可见, 设弹层可见] = useState(false);
  // 递交简历段的 PDF 附件（标注 09:23）：看的是收到的 PDF 原件
  const [看简历文件名, 设看简历文件名] = useState<string | null>(null);
  const [决策快照, 设决策快照] = useState<决策快照内容 | null>(null);
  // 终止是本屏唯一不可逆的动作，且与「接受」并排 —— 先过一道确认，
  // 与「删除岗位」「解除屏蔽」「关闭职位」同一套确认框（组件/确认层）
  const [待终止, 设待终止] = useState(false);

  // 进入页面自动定位到当前需要行动的阶段段（与求职端同构）
  const 当前节点引用 = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const 定时 = window.setTimeout(() => {
      当前节点引用.current?.scrollIntoView({ block: 'start', behavior: 'smooth' });
    }, 120);
    return () => window.clearTimeout(定时);
  }, []);

  // 从一位候选切到另一位时（同路由只换参数，组件不重挂载）：Tab 回到进度，
  // 不把上一位的视图带给下一位（与求职端 在谈详情 同构）。
  // 挂载也会跑一次：初始 Tab 由 ?tab=resume 深链决定，所以换单判定用 ref 记住上一位。
  const 已见编号引用 = useRef(编号);
  useEffect(() => {
    if (已见编号引用.current !== 编号) {
      已见编号引用.current = 编号;
      设当前Tab('进度');
    }
  }, [编号]);

  // 「终止」会把这位候选从在谈列表里移除（归档），页面必须留一份快照，
  // 否则用户点完「不合适 · 终止」整屏会瞬间跳成已归档提示，看不到决策回执。
  const 列表内候选 = 状态.企业候选列表.find((条) => 条.编号 === 编号);
  const [快照候选, 设快照候选] = useState<候选 | null>(列表内候选 ?? null);
  useEffect(() => {
    if (列表内候选) 设快照候选(列表内候选);
  }, [列表内候选]);
  const 候 = 列表内候选 ?? 快照候选;

  // 协调阶段的决策来自全局状态，跨屏可见（人才页那张卡会跟着变）
  const 协调决策: '接受' | '终止' | null = 状态.候选决策[编号] ?? null;

  // 叮嘱：就地输入，落全局 叮嘱表（按候选编号归档），产物接在写下它的那个阶段流末尾
  const [叮嘱草稿, 设叮嘱草稿] = useState('');
  const 本候叮嘱 = 状态.叮嘱表[编号] ?? [];
  const 发叮嘱 = () => {
    const 内容 = 叮嘱草稿.trim();
    if (内容 === '' || !候) return;
    // 带上写下这句话时所处的阶段：之后推进到下一阶段，这条话仍留在原来那一段流里
    派发({ 型: '加叮嘱', 归属: 编号, 文本: 内容, 序号: 本候叮嘱.length + 1, 写于阶段: 候.阶段 });
    设叮嘱草稿('');
  };

  // 直接进 URL 但这位候选从来不存在（或刷新后状态已丢）时的兜底
  if (!候) {
    return (
      <次级页外壳>
        <返回栏 返回={返回} 标题="这位候选已归档" />
        <div className={样式.已归档区}>
          这位候选已不在「在谈」列表里。
          <br />
          可能你选择了终止，AI代理已停止接触并归档，不再消耗接触额度。
        </div>
      </次级页外壳>
    );
  }

  const 已完成阶段 = 候选阶段小结[编号] ?? [];
  const 当前阶段序 = 阶段顺序.indexOf(候.阶段);

  // 招聘方点开 S1 附件看到该候选人自己的原件投影；S0 候选（真名为空）没有原件投影，
  // 退回代号 + 打码联系方式分支。原件文件名来自被点击的附件数据，不按真名重新生成
  const 原件投影 = 候.真名
    ? (候选简历原件表[候.编号] ?? 候选简历原件表[候.编号.split('@')[0]])
    : undefined;

  // 意向节点是「等你确认」还是「已确认」：真名在 S1 原件递交时已写入初始 Mock，不能再用它
  // 判断 S3 是否完成；只用「候选确认意向」写入的辅助文案「去消息页私聊」作为 S3 完成信号
  const 意向已确认 = 候.阶段 === '意向确认' && 候.辅助文案 === '去消息页私聊';

  // 协调节点在两种情况下要渲染：① 还卡着等你拍板；② 已经拍了（要显示回执，不能凭空消失）
  const 显示协调节点 = (候.阶段 === '需要协调' && 候.需要你) || 协调决策 !== null;

  // 底部就地输入与求职端同构。详情统一 Task 9（spec §5「Mock 同类终局也只读」）：终局
  // 只读条只消费本屏已有的完成/归档事实 —— 归档 = 已移出企业候选列表（本屏靠快照候选
  // 回看），完成 = 意向已确认（辅助文案「去消息页私聊」）；「进入意向确认阶段」不是完成。
  const 底栏信息: 详情底栏信息 = 列表内候选 === undefined || 意向已确认
    ? { kind: '只读', 说明: '当前在谈已结束，仅可查看' }
    : {
        kind: '输入',
        占位: 候.阶段 === '需要协调' && 候.需要你
          ? '你的条件是什么？直接告诉代理'
          : '有想法就告诉你的AI代理',
        值: 叮嘱草稿,
        改变: 设叮嘱草稿,
        发送: 发叮嘱,
        禁用说明: null,
      };

  // 决策落地：先把卡点上下文冻结成快照，再写全局状态（人才页那张卡同步变），最后升起
  // 「要我记住这个判断吗」弹层。顺序不能颠倒 —— reducer 的「候选接受方案」会清掉 分歧、
  // 改写 下一步，派发之后再算文案就只剩空壳（会出现「这一项差 以内的」这种残句）。
  const 做协调决策 = (类型: '接受' | '终止') => {
    设决策快照({ 分歧: 候.分歧, ...算决策文案(候, 类型) });
    派发(类型 === '接受' ? { 型: '候选接受方案', 编号 } : { 型: '候选终止', 编号 });
    设弹层可见(true);
  };

  // ── 详情统一 Task 8：协调/意向两张决策卡改走共用 详情动作卡（组件/在谈详情）──
  // 事实块（卡点说明/数字对比/方案条/决策尾注/决策回执/节点说明/确认警示）进正文槽，
  // 按钮由本连接层派发原型动作（候选接受方案/候选终止/候选确认意向 + 拿不准弹层的
  // 规则入口），零 P5 请求。
  const 协调卡信息: 详情动作卡信息 = {
    键: '协调决策',
    标题: '卡点决策',
    说明: null,
    正文: (
      <协调事实块
        候={候}
        分歧={候.分歧 ?? 决策快照?.分歧 ?? 状态.候选决策快照[编号] ?? null}
        决策={协调决策}
      />
    ),
    // 已拍板（接受/终止）只留回执，不再挂按钮
    按钮们: 协调决策 === null
      ? [
          {
            键: '终止',
            文案: 企业卡点决策.退出按钮,
            外观: '次要',
            禁用说明: null,
            执行: () => 设待终止(true),
          },
          {
            键: '接受',
            文案: '接受',
            外观: '主要',
            禁用说明: null,
            执行: () => 做协调决策('接受'),
          },
        ]
      : [],
  };

  const 意向卡信息: 详情动作卡信息 = {
    键: '意向确认',
    标题: '确认意向',
    说明: null,
    正文: (
      <>
        <div className={样式.节点说明}>
          {意向已确认 ? `候选人是 ${候.真名 ?? 候.代号}` : '条件已回报一致，等你先确认意向。'}
        </div>
        {/* 确认警示不能再删（企业侧唯一告知面）；随共用卡的正文槽排在按钮上方 */}
        <div className={样式.确认警示}>{企业意向确认警示}</div>
      </>
    ),
    按钮们: [
      {
        键: '开始私聊',
        文案: '开始私聊 ›',
        外观: '主要',
        禁用说明: null,
        // 标注 18:44：只统一文案，没省掉确认这一步 —— 未确认时这一下仍派发 候选确认意向
        执行: 意向已确认 ? () => 跳转(路径.企业真人会话) : () => {
          派发({ 型: '候选确认意向', 编号 });
          跳转(路径.企业真人会话);
        },
      },
    ],
  };

  // ── 谈判进度：把四个阶段摊成一条对话流的分段数据（与求职端同构）──────────
  const 小结表 = new Map<阶段, 阶段小结>(已完成阶段.map((段) => [段.阶段, 段]));
  // 剧本候选读自己的对话；发岗播种与推荐克隆进来的候选没有剧本，
  // 用他自己的字段拼一段兜底往来 —— 每张卡点开都要看得见双方代理在交互
  const 本候对话 = 各候选阶段对话[编号] ?? 候选兜底对话(候);

  const 分段们: 分段项[] = 阶段顺序.map((名, 序) => {
    const 段小结 = 小结表.get(名);
    const 对话 = 本候对话[名];
    const 态: 分段项['态'] =
      序 < 当前阶段序 ? '已完成' : 序 === 当前阶段序 ? '当前' : '未到达';

    // 状态胶囊：协调阶段拍过板就说结果，其余走小结自带的状态
    const 状态文 =
      名 === '需要协调' && 协调决策
        ? 协调决策 === '接受'
          ? '已放宽'
          : '已终止'
        : 名 === '需要协调' && 态 === '当前'
          ? '需要你'
          : 名 === '意向确认' && 态 === '当前'
            ? 意向已确认
              ? '已确认'
              : '需要你'
            : (段小结?.状态 ?? (态 === '已完成' ? '通过' : '进行中'));

    return {
      阶段: 名,
      态,
      状态文: 态 === '未到达' ? null : 状态文,
      // 当前阶段没有剧本小结时，退回卡片上的下一步文案，段内不至于空着
      // 代理小结只属于「已经聊完、推进到下一阶段」的段（用户 2026-08-20）：
      // 进行中的阶段还没有结论，不摆小结块；卡住的阶段结论由决策卡自己带一行
      小结: 态 === '已完成' ? (段小结?.小结 ?? null) : null,
      核对清单: 态 === '已完成' ? 段小结?.核对清单 : undefined,
      // 递交简历段没有对话数据时，仍要给出收到的那份匿名简历原件
      附件:
        名 === '递交简历' && !对话?.length && 态 !== '未到达'
          ? { 文件名: `${候.代号}_简历.pdf` }
          : null,
      对话,
      // 进往来记录的那类链接在本次重构里去掉了（对话已经在流里），只留就地切 Tab 的
      小链接: 段小结?.链接 && !段小结.链接.includes('往来') ? 段小结.链接 : null,
      // 按「写下时所在的阶段」归段，不按当前阶段 —— 否则谈判一推进，旧话会整批跳到新段
      用户气泡: 本候叮嘱.filter((条) => 条.写于阶段 === 名),
      待推进说明:
        名 === '意向确认'
          ? '双方确认后进入真人沟通与约面'
          : '前一阶段通过后 AI 代理自动推进',
      // 段内一条对话一句小结都没有时的兜底行：聊完的段说「已通过」，
      // 还在跑的段退回卡片上的下一步，不能拿「已通过」去描述进行中的阶段
      空说明: 态 === '已完成' ? '已通过 · AI代理自动推进' : 候.下一步,
      默认展开: 名 === '需要协调' && 协调决策 !== null ? true : undefined,
      尾部:
        名 === '需要协调' && 显示协调节点 ? (
          <详情动作卡 信息={协调卡信息} />
        ) : 名 === '意向确认' && 候.阶段 === '意向确认' ? (
          <详情动作卡 信息={意向卡信息} />
        ) : undefined,
    };
  });

  // 顶栏信息（共用外壳契约）：去名裁定（2026-09-09 产品负责人：「招聘端的用户都已经是
  // 匿名了，左上角的名字也应该删掉」）—— 标题位给画像行（性别 + 年限｜学历｜求职状态，
  // 年限取 画像 首段、学历取 候.学历、状态取 在找「·」后半段），标题/别名不传；
  // 副标题 = 画像 去掉首段年限。句子里的称呼（决定文案 / 终止弹层 / 附件文件名 / 规则来源）不动。
  const { 年限: 顶栏年限, 其余: 顶栏副标题 } = 拆画像(候.画像);
  const 顶栏: 顶栏信息 = {
    端: '招聘',
    标题: null,
    副标题: 顶栏副标题,
    画像: {
      性别: 候.性别 ?? null,
      年限: 顶栏年限,
      学历: 候.学历 ?? null,
      求职状态: 候.在找?.split(' · ')[1] ?? null,
    },
    右侧: { kind: '分数', 值: 候.匹配分 },
    岗位上下文: null,
  };

  return (
    <详情外壳
      信息={顶栏}
      返回={返回}
      当前Tab={当前Tab}
      切Tab={设当前Tab}
      进度={
        // 一条流：阶段分节条 → 该阶段双方代理对话 → 你的话 → 决策卡（与求职端同构）
        <阶段对话流
          分段们={分段们}
          当前段引用={当前节点引用}
          点附件={设看简历文件名}
          点链接={() => 设当前Tab('资料')}
        />
      }
      资料={<在线简历Tab 候={候} />}
      底栏={
        // 底部输入/终局只读由共用 详情底栏 渲染（输入态内部仍是全站 真输入条）
        <详情底栏 信息={底栏信息} />
      }
      弹层={
        <>
          {/* 拿不准 → 记成规则：只在协调决策后升起；意向确认没有可沉淀的分歧项。
              弹层组件的决策类型只认求职端的 '退出'，企业侧的 '终止' 映射过去 */}
          <拿不准弹层
            可见={弹层可见}
            关闭={() => 设弹层可见(false)}
            决策类型={协调决策 === '终止' ? '退出' : 协调决策}
            决定文案={决策快照?.决定文案}
            规则草案={决策快照?.规则草案}
            记成规则={(内容: string) => {
              // 写规则归 企业代理设置（canonical）：收起弹层并落 Mock 规则，跳设置页当场
              // 看到。本组件只在 Mock 分支挂载（P5 接线后 Backend 走共享详情），没有
              // 第二种模式判断。
              设弹层可见(false);
              派发({
                型: '企业新增规则',
                内容: 内容 || 决策快照?.规则草案 || 候.下一步,
                来源: `来自「${候.代号}」单的决策`,
              });
              跳转(路径.企业代理设置);
            }}
          />
          {看简历文件名 ? (
            <简历预览层
              文件名={看简历文件名}
              候选原件={原件投影}
              匿名代号={原件投影 ? undefined : 候.代号}
              关闭={() => 设看简历文件名(null)}
            />
          ) : null}

          {/* 终止二次确认：确认后这位候选立刻移出在谈列表，只能去「历史代谈」回看 */}
          {待终止 ? (
            <确认层
              标题={`终止「${候.代号}」？`}
              正文={归档口径}
              执行文="终止"
              取消={() => 设待终止(false)}
              执行={() => {
                设待终止(false);
                做协调决策('终止');
              }}
            />
          ) : null}
        </>
      }
    />
  );
}

// ── D5·C 需要协调 · 卡点决策的事实块（详情统一 Task 8）──────────────────────
// 卡的标题/按钮归共用 详情动作卡（按钮在连接层组装、派发原型动作）；这里只剩事实：
// 卡点说明（无分歧条时）/ 数字对比 / 已拍板时的决策回执或未拍板时的方案条 + 决策尾注。
function 协调事实块({
  候,
  分歧: 差额,
  决策,
}: {
  候: 候选;
  /** 由调用方给：当前分歧，接受后退回决策前的快照 */
  分歧: 分歧 | null;
  决策: '接受' | '终止' | null;
}) {
  return (
    <>
      {/* 有分歧条时不再重复说明（用户 2026-08-20：太复杂），只留 分歧 → 方案 → 决策 */}
      {差额 ? null : (
        <div className={样式.卡点说明}>
          {/* A-01（沈亦舟）用设计稿定稿小结；其余候选退回卡片上的辅助文案 */}
          {候.编号 === 'A-01' ? 卡点小结A01 : 候.辅助文案 ?? 候.下一步}
        </div>
      )}

      {/* 数字对比：双方条件在这一阶段已可披露，直接把差额摊开给你看 */}
      {差额 ? (
        <div className={样式.数字对比}>
          <div className={样式.对比列}>
            <span className={样式.对比标}>岗位条件</span>
            <span className={`${样式.对比值} 等宽数字`}>{差额.我方}</span>
          </div>
          <div className={样式.对比差}>
            <span className={`${样式.对比差值} 等宽数字`}>{差额.差值}</span>
          </div>
          <div className={`${样式.对比列} ${样式.对比列右}`}>
            <span className={样式.对比标}>候选条件</span>
            <span className={`${样式.对比值} 等宽数字`}>{差额.对方}</span>
          </div>
        </div>
      ) : null}

      {决策 ? (
        <div className={样式.决策回执}>
          {决策 === '接受'
            ? '已告知AI代理：接受该方案，它会回报对方，等候选人确认意向。'
            : '已告知AI代理：终止这一单，不再消耗接触额度。'}
        </div>
      ) : (
        <>
          {/* 方案条（标注 00:12）：条款放上面说清，按钮只留动作（按钮在共用卡的键行里） */}
          {候.方案 ? (
            <div className={样式.方案条}>
              <span className={样式.方案标}>方案</span>
              <span className={样式.方案值}>{候.方案}</span>
            </div>
          ) : null}
          <div className={样式.决策尾注}>{企业卡点决策.尾部说明}</div>
        </>
      )}
    </>
  );
}

// ── D11·A 在线简历 Tab：与独立屏（匿名在线简历）共用同一份正文（组件/在谈详情/在线简历正文）──
// 在线简历的脱敏段只在双方意向确认（S3）后还原实名；S0/S1/S2 候选仍走代号匿名版，
// 真名在 S1 原件递交时已向招聘方披露（看简历原件弹层），不等于在线简历也已去匿名。
// 详情统一（Task 4）：详情显式传 完整布局 —— 无档的候选不再换一张「未同步」短句，
// 而是同一份正文里逐区显示缺失（与 Backend 的缺失布局同一组 JSX）；独立屏默认不变。
function 在线简历Tab({ 候 }: { 候: 候选 }) {
  const { 状态 } = use应用状态();
  // 滚动壳归共用外壳所有，这里只给 资料 槽位的正文
  const 档 = 匿名简历表[候.编号] ?? 匿名简历表[候.编号.split('@')[0]] ?? null;
  // 身份显示按 spec §3.2 消费真名事实：S1 原件递交后真名非空即显示真名/还原公司实名；
  // 已确认（S3）只承担意向确认文案，不兼任身份披露权限。
  const 已确认 = 候.阶段 === '意向确认' && 候.辅助文案 === '去消息页私聊';
  return (
    <在线简历正文
      档={档}
      完整布局
      真名={候.真名}
      已确认={已确认}
      对齐行们={
        档 === null
          ? null
          : 招聘侧对齐行(状态.岗位列表.find((岗) => 岗.编号 === 候.岗位编号)?.硬性条件 ?? [], 档)
      }
      // 头行求职状态与顶栏同源：在找「·」后半段（2026-09-09 第二批去名）
      求职状态={候.在找?.split(' · ')[1] ?? null}
    />
  );
}
